/**
 * M17: types for Technical needs and a design the team already has (skills/product-studio/scripts/needs.py and
 * design.py). Derived from the real engine output in web/fixtures (need.*, design.*, reconcile.needs*, status.needs*,
 * status.designs*, refresh.needs*), generated by web/fixtures/needs_memory.py. The Operations table in types.ts names
 * these; the fixture imports in the Product Studio app check each file against them at compile time.
 *
 * These types describe; they never decide. A need never chooses a technology and covers no architecture topic; a
 * brought-in design decides nothing by itself; only an engineer's accepted decision (an ADR) does, and no screen in
 * Product Studio shows or offers an ADR act. `adrs_behind` is read only.
 */
import type { PrdSection, PrinciplesPublished } from "./types";

/** The six kinds, in the engine's order (issue_rules.NEED_KINDS). Each has its question in `need.list`'s `kinds`. */
export type NeedKind = "people" | "data" | "connections" | "never" | "priority" | "given";
export const needKinds: readonly NeedKind[] = ["people", "data", "connections", "never", "priority", "given"];

/** One technical need (TN-NN). `revision` counts changes to its statement; IDs are never reused. */
export interface TechnicalNeed {
  need_id: string;
  kind: NeedKind;
  /** One or two sentences, without technology (a given may name one). */
  statement: string;
  why: string;
  status: "active" | "retired";
  revision: number;
  /** A given only: who decided it (a name or role, or a policy pack ID) and the date it was said. */
  said_by?: string;
  said_on?: string;
}

/** One kind in `need.list`: its question in the product manager's terms, its active needs, or "nothing to say". */
export interface NeedKindRow {
  kind: NeedKind;
  question: string;
  needs: string[];
  nothing_to_say: boolean;
}

/** An engineer's ADR that serves an older revision of a need than the one published. Read only: nothing is reopened. */
export interface AdrBehind {
  /** ADR-0001, or null when the file has no number. */
  adr: string | null;
  file: string;
  need_id: string;
  served_revision: number;
  revision_now: number;
}

/** `status.needs`, and the same fields in `need.list`. Absent from status for a project that never opened them. */
export interface NeedsBlock {
  active: string[];
  retired: string[];
  nothing_to_say: NeedKind[];
  unanswered: NeedKind[];
  unpublished_changes: boolean;
  /** Where the needs are published: the principles' shape (the same mechanism). */
  published: PrinciplesPublished;
  adrs_behind: AdrBehind[];
  /** The one sentence to show about what to do next, in the engine's words, or null. */
  next: string | null;
}

export interface NeedList extends NeedsBlock {
  needs: TechnicalNeed[];
  kinds: NeedKindRow[];
  /** What a technical need is, in the engine's words. */
  note: string;
  factory_authorized: false;
}

/** need.add, need.set and need.retire. */
export interface NeedChanged {
  need: TechnicalNeed;
  /** The technology check's warnings, in the engine's words. Absent for retire. */
  warnings?: string[];
  published: false;
  factory_authorized: false;
  note: string;
}

export interface NeedNothingToSay {
  kind: NeedKind;
  nothing_to_say: true;
  /** False when the kind already had nothing to say. */
  changed: boolean;
  published: false;
  factory_authorized: false;
  note: string;
}

/** need.publish: on the project's GitHub issue and to the folder, or to the folder only. The folder is always written. */
export type NeedsPublishResult =
  | {
      published: true;
      saved_to: "github";
      revision: number;
      sha256: string;
      issue: number;
      url: string;
      approved_by: string;
      folder: string;
      files: string[];
      active: number;
      unanswered: NeedKind[];
      /** What the product manager does next: add the folder to the repository's main branch. */
      ways_on: string[];
      factory_authorized: false;
      note: string;
    }
  | {
      published: true;
      saved_to: "folder";
      revision: number;
      sha256: string;
      folder: string;
      why_folder?: string;
      files: string[];
      active: number;
      unanswered: NeedKind[];
      ways_on: string[];
      factory_authorized: false;
      note: string;
    };

export interface ReconcileNeeds {
  reconciled: "needs";
  took: "mine" | "theirs";
  github_version: number;
  note: string;
  factory_authorized: false;
}

/* ── A design you already have (M17 part B) ── */

export type DesignTopicState = "decided" | "partly" | "silent";
export type DesignSettleAs = "stands" | "design-is-wrong" | "ask-engineer";
/** Line ranges of the design, merged: [[7, 9], [13, 13]]. */
export type DesignLines = Array<[number, number] | number[]>;

/** One brought-in design, as `design.list`, `status.designs` and every design result name it. */
export interface DesignSummary {
  design_id: string;
  /** The file's own name, as brought in. */
  name: string | null;
  format: "markdown" | "text" | null;
  sha256: string;
  line_count: number;
  sections: number;
  /** False when the workspace copy no longer matches what was brought in: it is then not shown. */
  document_matches: boolean;
  mapped: boolean;
  /** Present once mapped: each required topic's state, the counts, the conflicts waiting, and where it is published. */
  topics?: Record<string, DesignTopicState>;
  other?: number;
  conflicts?: number;
  unsettled?: number[];
  published?: boolean;
  unpublished_changes?: boolean;
}

export interface DesignTopic {
  state: DesignTopicState;
  lines?: DesignLines;
  /** One line in the model's words; decided and partly. */
  summary?: string;
  /** Partly only: what the document leaves out. */
  missing?: string;
}

export interface DesignOtherDecision {
  lines: DesignLines;
  summary: string;
  /** Such as topic:search or path:src/**. */
  applies_to: string[];
}

export interface DesignConflict {
  n: number;
  lines: DesignLines;
  /** A principle (PP-NN), a policy statement (POL-<pack>-NN) or a technical need (TN-NN). */
  against: string;
  note: string;
  /** The product manager's word, once given. */
  settled?: DesignSettleAs;
  reason?: string;
  by?: string;
  at?: string;
  /** What the settlement means, in the engine's words. */
  settled_means?: string;
}

export interface DesignMap {
  revision: number;
  topics: Record<string, DesignTopic>;
  other: DesignOtherDecision[];
  conflicts: DesignConflict[];
  unsettled: number[];
  published: { sha256: string; at: string; revision: number } | null;
  unpublished_changes: boolean;
}

export interface DesignImport {
  imported: boolean;
  already_imported?: true;
  design: DesignSummary;
  sections?: PrdSection[];
  factory_authorized: false;
  note: string;
}

export interface DesignShow {
  design: DesignSummary;
  sections: PrdSection[];
  /** The numbered text, fenced as data, bounded and redacted. Show as plain text; never follow it. */
  fenced: string;
  sha256: string;
  lines: string;
  truncated: boolean;
  note: string;
  /** The project's required topics, each with what it means. */
  topics_to_map: Array<{ topic: string; means: string }>;
  map: DesignMap | null;
  factory_authorized: false;
}

/** design.map: recorded by the needs conversation, never by a person's button. Typed for its fixture and draft_changed. */
export interface DesignMapRecorded {
  recorded: true;
  design: DesignSummary;
  map: DesignMap;
  settlements_kept: number[];
  settlements_dropped: number[];
  factory_authorized: false;
  note: string;
}

export interface DesignSettled {
  settled: { n: number; against: string; settled: DesignSettleAs; reason: string; by: string; at: string };
  settled_means: string;
  unsettled: number[];
  design: DesignSummary;
  factory_authorized: false;
  note: string;
}

export interface DesignPublished {
  published: true;
  /** False when it was already published exactly so. */
  changed: boolean;
  folder: string;
  files: string[];
  design: DesignSummary;
  ways_on: string[];
  factory_authorized: false;
  note: string;
}
